CPU.write_state:
/Function(function ( vec ) {
                                                  if (typeof vec.CPU == "undefined") {
                                                      vec.CPU = {} ;
					          }

					          // var internal_reg = ["PC", "MAR", "MBR", "IR", "RT1", "RT1", "RT2", "SR"] ;
					          var internal_reg = ["PC", "SR"] ;

						  var value = 0 ;
					          for (var i=0; i<sim_p.states.BR.length; i++)
						  {
						      value = parseInt(get_value(sim_p.states.BR[i])) >>> 0;
						      if (value != 0) {
							  vec.CPU["R" + i] = {"type":  "register",
								              "default_value": 0x0,
								              "id":    "R" + i,
								              "op":    "=",
								              "value": "0x" + value.toString(16)} ;
						      }
						  }

					          for (var i=0; i<internal_reg.length; i++)
						  {
						      value = parseInt(sim_p.states['REG_' + internal_reg[i]].value) >>> 0;
						      if (value != 0) {
							  vec.CPU[internal_reg[i]] = {"type":  "register",
								                      "default_value": 0x0,
								                      "id":    internal_reg[i],
								                      "op":    "=",
								                      "value": "0x" + value.toString(16)} ;
						      }
						  }

						  return vec;
				               })/

CPU.read_state:
/Function(function ( vec, check ) {
                                                  if (typeof vec.CPU == "undefined")
                                                      vec.CPU = {} ;

					          var key = check["id"].toUpperCase().trim() ;
					          var val = parseInt(check["value"]).toString(16) ;
					          if ("REGISTER" == check["type"].toUpperCase().trim())
                                                  {
						      vec.CPU[key] = {"type":  "register",
								      "default_value": 0,
								      "id":    key,
								      "op":    check["condition"],
								      "value": "0x" + val} ;
                                                      return true ;
                                                  }

                                                  return false ;
				              })/

CPU.get_state:
/Function(function ( reg ) {
					          var r_reg = reg.toUpperCase().trim() ;
					          if (typeof sim_p.states['REG_' + r_reg] != "undefined") {
					              var value = get_value(sim_p.states['REG_' + r_reg]) >>> 0;
					              return "0x" + value.toString(16) ;
					          }

					              r_reg = r_reg.replace('R','') ;
					          var index = parseInt(r_reg) ;
					          if (typeof sim_p.states.BR[index] != "undefined") {
					              var value = get_value(sim_p.states.BR[index]) >>> 0;
					              return "0x" + value.toString(16) ;
					          }

					          return null ;
				              })/

CPU.get_value:
/Function(function ( elto ) {
                                                    var r_ref = simhw_sim_state_getref(elto) ;
                                                    if (typeof r_ref == "undefined") {
                                                        throw new Error("unknown element named " + elto) ;
                                                    }

                                                    return (get_value(r_ref) >>> 0) ;
				              })/

CPU.set_value:
/Function(function ( elto, value ) {
						    var pc_name = simhw_sim_ctrlStates_get().pc.state ;
						    if (pc_name === elto) {
							show_asmdbg_pc() ;
						    }

                                                    var r_ref = simhw_sim_state_getref(elto) ;
                                                    if (typeof r_ref == "undefined") {
                                                        throw new Error("unknown element named " + elto) ;
                                                    }

                                                    return set_value(r_ref, value) ;
				              })/

MEMORY.write_state:
/Function(function ( vec ) {
                                                  if (typeof vec.MEMORY == "undefined")
                                                      vec.MEMORY = {} ;

						  var key = 0 ;
						  var value = 0 ;
					          for (var index in sim_p.internal_states.MP)
						  {
                                                       value = main_memory_getvalue(sim_p.internal_states.MP,
                                                                                    index) ;
                                                       value = parseInt(value) ;
						       if (value != 0)
						       {
					                   key = parseInt(index).toString(16) ;
							   vec.MEMORY["0x" + key] = { "type":  "memory",
								                      "default_value": 0x0,
								                      "id":    "0x" + key,
								                      "op":    "=",
								                      "value": "0x" + value.toString(16) } ;
						       }
						  }

						  return vec;
				              })/

MEMORY.read_state:
/Function(function ( vec, check ) {
                                                  if (typeof vec.MEMORY == "undefined") {
                                                      vec.MEMORY = {} ;
                                                  }

					          var key = parseInt(check.id).toString(16) ;
					          var val = parseInt(check.value).toString(16) ;
					          if ("MEMORY" == check.type.toUpperCase().trim())
                                                  {
						      vec.MEMORY["0x" + key] = { "type":  "memory",
							  	                 "default_value": 0x0,
								                 "id":    "0x" + key,
								                 "op":    check.condition,
								                 "value": "0x" + val } ;
                                                      return true ;
                                                  }

                                                  return false ;
				             })/

MEMORY.get_state:
/Function(function ( pos ) {
						  var index = parseInt(pos) ;
                                                  var value = main_memory_getvalue(sim_p.internal_states.MP,
                                                                                   index) ;
						  if (typeof value === "undefined") {
					              return null ;
					          }

						  return "0x" + parseInt(value).toString(16) ;
				             })/

MEMORY.get_value:
/Function(function ( elto ) {
                                                 var value = main_memory_getvalue(sim_p.internal_states.MP,
                                                                                  elto) ;
				                 show_main_memory(sim_p.internal_states.MP, elto, false,false) ;
                                                 return (value >>> 0) ;
				             })/

MEMORY.set_value:
/Function(function ( elto, value ) {
						 // PC
						 var origin = '' ;
                                                 var r_value = main_memory_get_program_counter() ;
                                                 if (r_value != null) {
						     origin = 'PC=0x' + r_value.toString(16) ;
						 }

						 var melto = {
								"value":           (value >>> 0),
								"source_tracking": [ origin ],
								"comments":        null
							     } ;
                                                 var valref = main_memory_set(sim_p.internal_states.MP,
                                                                              elto, 
									      melto) ;

				                 show_main_memory(sim_p.internal_states.MP, 
                                                                  elto, 
                                                                  (typeof valref === "undefined"),
                                                                  true) ;

						 return value ;
				             })/

